DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef(oid) INTO definition FROM pg_proc WHERE proname='launch_notification_tick' AND pronamespace='public'::regnamespace; IF strpos(definition,'season_id=a.season_id')=0 THEN RAISE EXCEPTION 'notification_contract_changed'; END IF; EXECUTE replace(definition,'FOR a IN SELECT * FROM announcements WHERE scheduled_at<=now() AND scheduled_at>now()-interval ''1 day'' AND NOT is_demo AND (country IS NULL OR country=p.country_code) AND (language IS NULL OR language=p.language) AND (season_id IS NULL OR EXISTS(SELECT 1 FROM season_entries WHERE season_id=a.season_id AND user_id=p.id))','FOR a IN SELECT ann.* FROM announcements ann WHERE ann.scheduled_at<=now() AND ann.scheduled_at>now()-interval ''1 day'' AND NOT ann.is_demo AND (ann.country IS NULL OR ann.country=p.country_code) AND (ann.language IS NULL OR ann.language=p.language) AND (ann.season_id IS NULL OR EXISTS(SELECT 1 FROM season_entries e WHERE e.season_id=ann.season_id AND e.user_id=p.id))');END $$;